import { TestBed } from '@angular/core/testing';
import { LoanService } from './loan.service';
import { EXAMPLE_LOANS } from './loan-example-data';
import { BookService } from '../book/book.service';
import { MemberService } from '../member/member.service';

describe('LoanService', () => {
  beforeEach(() => TestBed.configureTestingModule({}));

  it('seeds from example data', () => {
    expect(TestBed.inject(LoanService).loans().length).toBe(EXAMPLE_LOANS.length);
  });

  it('creates a record with a fresh id and returns it', () => {
    const service = TestBed.inject(LoanService);
    const before = service.loans().length;
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    expect(service.loans().length).toBe(before + 1);
    expect(service.byId(created.id)?.reference).toEqual(created.reference);
    expect(created.memberIds).toEqual([]);
  });

  it('updates only the fields it is given', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    service.update(created.id, { reference: 'Changed' });
    expect(service.byId(created.id)?.reference).toEqual('Changed');
    expect(service.byId(created.id)?.branch).toEqual(created.branch);
  });

  it('removes a record', () => {
    const service = TestBed.inject(LoanService);
    const created = service.create({
      reference: 'Test reference',
      branch: 'Test branch',
      status: 'Requested',
      extended: false,
      bookId: null,
      borrowedOn: '2026-01-01',
      remarks: '',
    });
    service.remove(created.id);
    expect(service.byId(created.id)).toBeUndefined();
  });

  it('detaches bookId once the Book it points at is removed', () => {
    const bookService = TestBed.inject(BookService);
    const service = TestBed.inject(LoanService);
    const linked = service.loans().find((item) => item.bookId !== null && item.bookId !== '');
    expect(linked).toBeDefined();
    bookService.remove(linked!.bookId!);
    TestBed.flushEffects();
    expect(service.byId(linked!.id)?.bookId).toBe(null);
  });

  it('detaches memberIds once the Member it points at is removed', () => {
    const memberService = TestBed.inject(MemberService);
    const service = TestBed.inject(LoanService);
    const assigned = service.loans().find((item) => item.memberIds.length > 0);
    expect(assigned).toBeDefined();
    const targetId = assigned!.memberIds[0];
    memberService.remove(targetId);
    TestBed.flushEffects();
    expect(service.byId(assigned!.id)?.memberIds).not.toContain(targetId);
  });

  it('lists the records for one Member', () => {
    const service = TestBed.inject(LoanService);
    const assigned = service.loans().find((item) => item.memberIds.length > 0)!;
    expect(service.forMember(assigned.memberIds[0]).map((item) => item.id)).toContain(assigned.id);
  });
});
